import json

# Generate the grid
output = [[0] * 30 for _ in range(30)]
content_rows = [2, 9, 16, 22, 27]
cell_cols = [3, 10, 17, 24]
band_values = [3, 2, 3, 2, 2]

for cell_row in range(5):
    center_row = content_rows[cell_row]
    value = band_values[cell_row]
    for cell_col in range(4):
        center_col = cell_cols[cell_col]
        for r in range(max(0, center_row-1), min(30, center_row+2)):
            for c in range(max(0, center_col-1), min(30, center_col+2)):
                if r == center_row and c == center_col:
                    output[r][c] = value
                elif abs(r - center_row) <= 1 and abs(c - center_col) <= 1:
                    output[r][c] = 4

output_flat = [v for row in output for v in row]

# Print final JSON on one line
print(json.dumps({"action": "submit", "grid": output_flat}))
